import {cleanFx} from './dsp.mjs';
const prepared=new WeakMap();
export async function prepareEffects(context,state){const owners=[state,...state.tracks,...state.clips];if(!owners.some(o=>{const f=cleanFx(o.fx);return f.enabled&&(f.compress||f.deess||f.noise||f.output||f.limiter);}))return;if(!context.audioWorklet)throw Error('Les traitements dynamiques nécessitent un navigateur compatible AudioWorklet.');if(!prepared.has(context))prepared.set(context,context.audioWorklet.addModule(new URL('./voice-worklet.js',import.meta.url)).catch(e=>{prepared.delete(context);throw e;}));await prepared.get(context);}
export function effectChain(context,raw){const fx=cleanFx(raw),nodes=[],input=context.createGain();nodes.push(input);let last=input;const add=node=>{last.connect(node);nodes.push(node);last=node;};if(fx.enabled){if(fx.highpass){const n=context.createBiquadFilter();n.type='highpass';n.frequency.value=fx.highpass;n.Q.value=.707;add(n);}for(const[key,type,frequency]of [['bass','lowshelf',180],['presence','peaking',3000],['air','highshelf',7000]])if(fx[key]){const n=context.createBiquadFilter();n.type=type;n.frequency.value=frequency;n.Q.value=.8;n.gain.value=fx[key];add(n);}if(fx.compress||fx.noise||fx.deess||fx.output||fx.limiter)add(new AudioWorkletNode(context,'onde-voice',{numberOfInputs:1,numberOfOutputs:1,outputChannelCount:[2],processorOptions:fx}));}return{input,output:last,disconnect:()=>nodes.forEach(n=>{n.disconnect();n.port?.postMessage('stop');})};}
